fn solve(n: i8) -> i8 {
    // For positive n, integer division n/2 truncates toward zero.
    // Closed‐form:
    //   if n is even, sum =  n/2
    //   if n is odd,  sum = (n/2) - n
    if n % 2 == 0 {
        n / 2
    } else {
        n / 2 - n
    }
}

